import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Middleware: basic session check
function requireAuth(req, res, next) {
  const token = req.headers['x-session-token'];
  if (!token || token.length < 16) return res.status(401).json({ error: 'unauthorized' });
  req.sessionToken = token;
  next();
}

// Search endpoint for internal asset inventory
app.get('/api/v2/assets/search', requireAuth, async (req, res) => {
  try {
    const { category, status, facility_id, fields } = req.query;

    // Build field list - defaults to safe set
    let selectFields = 'id, name, category, status, facility_id, last_audit_date';
    if (fields) {
      // Allow caller to specify return fields for bandwidth optimization
      const requested = fields.split(',').map(f => f.trim());
      const allowed = ['id','name','category','status','facility_id','last_audit_date','serial_number','purchase_date','assigned_to','notes','cost_center'];
      const validated = requested.filter(f => allowed.includes(f));
      if (validated.length > 0) selectFields = validated.join(', ');
    }

    // Build WHERE clause
    let conditions = ['deleted_at IS NULL'];
    let params = [];
    let paramIdx = 1;

    if (category) {
      conditions.push(`category = $${paramIdx++}`);
      params.push(category);
    }
    if (status) {
      conditions.push(`status = $${paramIdx++}`);
      params.push(status);
    }
    if (facility_id) {
      conditions.push(`facility_id = $${paramIdx++}`);
      params.push(facility_id);
    }

    const whereClause = conditions.join(' AND ');

    // Sort parameter - used for flexible reporting
    const sortCol = req.query.sort || 'name';
    const sortDir = req.query.dir === 'desc' ? 'DESC' : 'ASC';

    const query = `SELECT ${selectFields} FROM assets WHERE ${whereClause} ORDER BY ${sortCol} ${sortDir} LIMIT 200`;

    const result = await pool.query(query, params);

    res.json({
      count: result.rows.length,
      assets: result.rows
    });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Bulk update endpoint
app.post('/api/v2/assets/bulk-update', requireAuth, async (req, res) => {
  const { asset_ids, updates } = req.body;
  if (!Array.isArray(asset_ids) || asset_ids.length === 0) {
    return res.status(400).json({ error: 'asset_ids required' });
  }

  const allowedUpdates = ['status', 'facility_id', 'assigned_to', 'notes'];
  const setClauses = [];
  const params = [];
  let paramIdx = 1;

  for (const [key, value] of Object.entries(updates || {})) {
    if (allowedUpdates.includes(key)) {
      setClauses.push(`${key} = $${paramIdx++}`);
      params.push(value);
    }
  }

  if (setClauses.length === 0) {
    return res.status(400).json({ error: 'no valid updates' });
  }

  const idPlaceholders = asset_ids.map((_, i) => `$${paramIdx + i}`).join(',');
  params.push(...asset_ids);

  const query = `UPDATE assets SET ${setClauses.join(', ')}, updated_at = NOW() WHERE id IN (${idPlaceholders})`;

  try {
    const result = await pool.query(query, params);
    res.json({ updated: result.rowCount });
  } catch (err) {
    console.error('Bulk update error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

app.listen(process.env.PORT || 3000);
